<?php require_once __DIR__.'/includes/bootstrap.php';require_manager();$pdo=db();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$unit=trim($_POST['unit']??'');$qty=(float)($_POST['quantity']??0);$reorder=(float)($_POST['reorder']??0);$cost=(float)($_POST['cost']??0);if($_POST['action']==='add'){$s=$pdo->prepare('INSERT INTO stock_items(name,unit,quantity_on_hand,reorder_level,unit_cost) VALUES(?,?,?,?,?)');$s->execute([$name,$unit,$qty,$reorder,$cost]);$id=$pdo->lastInsertId();$m=$pdo->prepare("INSERT INTO stock_movements(stock_item_id,user_id,movement_type,quantity_change,note) VALUES(?,?,'opening',?,'Opening balance')");$m->execute([$id,$_SESSION['user']['id'],$qty]);$msg='Stock item added.';}elseif($_POST['action']==='adjust'){$id=(int)$_POST['id'];$delta=(float)$_POST['delta'];$pdo->beginTransaction();$s=$pdo->prepare('UPDATE stock_items SET quantity_on_hand=quantity_on_hand+? WHERE id=? AND quantity_on_hand+?>=0');$s->execute([$delta,$id,$delta]);if(!$s->rowCount()){$pdo->rollBack();$msg='Adjustment would make stock negative.';}else{$m=$pdo->prepare("INSERT INTO stock_movements(stock_item_id,user_id,movement_type,quantity_change,note) VALUES(?,?,'adjustment',?,?)");$m->execute([$id,$_SESSION['user']['id'],$delta,trim($_POST['note'])]);$pdo->commit();$msg='Stock updated.';}}}
$rows=$pdo->query('SELECT * FROM stock_items ORDER BY name')->fetchAll();$pageTitle='Inventory';require 'includes/header.php';?>
<?php if($msg):?><div class="alert success"><?=e($msg)?></div><?php endif;?><div class="panel"><h2>Add stock item</h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="add"><div><label>Item name</label><input name="name" required></div><div><label>Unit (pieces, kg, litres)</label><input name="unit" required></div><div><label>Opening quantity</label><input name="quantity" type="number" step="0.001" min="0" value="0"></div><div><label>Reorder level</label><input name="reorder" type="number" step="0.001" min="0" value="0"></div><div><label>Unit cost (USD)</label><input name="cost" type="number" step="0.01" min="0" value="0"></div><div class="form-action"><button class="btn primary">Add stock item</button></div></form></div><div class="panel"><div class="panel-head"><div><h2>Stock on hand</h2><p class="muted">Ingredient and packaged-product quantities</p></div></div><div class="table-wrap"><table><thead><tr><th>Stock item</th><th>Available</th><th>Reorder at</th><th>Unit cost</th><th>Status</th><th>Adjust</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['name'])?></b></td><td><?=number_format($r['quantity_on_hand'],3).' '.e($r['unit'])?></td><td><?=number_format($r['reorder_level'],3)?></td><td><?=money($r['unit_cost'])?></td><td><span class="status <?=$r['quantity_on_hand']<=$r['reorder_level']?'voided':'completed'?>"><?=$r['quantity_on_hand']<=$r['reorder_level']?'Low stock':'In stock'?></span></td><td><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="adjust"><input type="hidden" name="id" value="<?=$r['id']?>"><input name="delta" type="number" step="0.001" placeholder="+/- qty" required><input name="note" placeholder="Reason"><button class="btn small secondary">Save</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="empty">No stock items yet. Add your stock items above.</td></tr><?php endif;?></tbody></table></div></div><?php require 'includes/footer.php';?>
